SaveData Load(string json)
{
    var save = JsonSerializer.Deserialize<SaveData>(json)!;
    if (save.Version < 2) save = save with { Version = 2, MaxHealth = 5 };   // version 1 had no MaxHealth
    return save;
}

string Describe(SaveData s) => $"v{s.Version} {s.Health}/{s.MaxHealth}";

record SaveData(int Version, uint Seed, int Health, int MaxHealth);

